SELECT COUNT(*) AS lustre_problem_count
FROM bgl_events
WHERE alert_label IN ('KERNMNTF', 'KERNMNT');

SELECT COUNT(*) AS total_rts_crashes
FROM bgl_events
WHERE alert_label IN ('KERNRTSP', 'KERNTERM');

SELECT COUNT(*) AS total_cache_parity_errors
FROM bgl_events
WHERE event_template IN (
  'instruction cache parity error corrected',
  'data cache search parity error detected. attempting to correct'
);
